with flattened_attrs as (select id, service, host, status_code, context, coalesce(context['region'], 'direct') as region_or_default, coalesce(context['trace'], 'direct') as trace_or_default, context['region'] as region from app_logs where status_code = 421) select id, status_code, trace_or_default, region, sum(status_code) over (partition by service) as service_sum_status_code, min(status_code) over (partition by host) as host_min_status_code, ntile(5) over (partition by host order by status_code, id) as status_code_bucket, ntile(3) over (partition by host, service order by status_code desc, id) as status_code_bucket_2, ntile(10) over (partition by host order by status_code desc, id) as status_code_bucket_3 from flattened_attrs;
